<?php
// Reads the exported cell coordinates, including TikTok's repeated XML row nodes.
function om_book($path){
 validate_xlsx_container($path);$z=new ZipArchive();if($z->open($path)!==true)throw new Exception('Cannot open workbook.');
 try{$shared=[];$s=$z->getFromName('xl/sharedStrings.xml');if($s){$x=XlsxReader::xml($s);foreach($x->query('//*[local-name()="si"]') as $si){$v='';foreach($x->query('.//*[local-name()="t"]',$si) as $t)$v.=$t->textContent;$shared[]=$v;}}
 $wb=XlsxReader::xml($z->getFromName('xl/workbook.xml'));$rels=XlsxReader::xml($z->getFromName('xl/_rels/workbook.xml.rels'));$map=[];foreach($rels->query('//*[local-name()="Relationship"]') as $r)if($r->getAttribute('TargetMode')!=='External')$map[$r->getAttribute('Id')]=$r->getAttribute('Target');$sheets=[];
 foreach($wb->query('//*[local-name()="sheets"]/*[local-name()="sheet"]') as $sheet){$rid='';foreach($sheet->attributes as $a)if($a->localName==='id')$rid=$a->value;$target=ltrim($map[$rid]??'','/');if(str_contains($target,'..')||str_contains($target,':'))throw new Exception('Invalid worksheet path.');if(!str_starts_with($target,'xl/'))$target='xl/'.$target;$x=XlsxReader::xml($z->getFromName($target));$grid=[];$cells=0;
 foreach($x->query('//*[local-name()="sheetData"]/*[local-name()="row"]/*[local-name()="c"]') as $c){if(++$cells>1000000)throw new Exception('Workbook exceeds one million cells.');if(!preg_match('/^([A-Z]+)([1-9][0-9]*)$/D',$c->getAttribute('r'),$m))throw new Exception('Invalid cell reference.');$rn=(int)$m[2];$col=XlsxReader::colIndex($m[1]);if($rn>10002||$col>255)throw new Exception('Use up to 10,000 order rows and 256 columns.');$type=$c->getAttribute('t');$v='';if($type==='inlineStr'){foreach($x->query('.//*[local-name()="t"]',$c) as $t)$v.=$t->textContent;}else{$n=$x->query('./*[local-name()="v"]',$c)->item(0);$v=$n?$n->textContent:'';if($type==='s')$v=$shared[(int)$v]??'';}if(isset($grid[$rn][$col])&&$grid[$rn][$col]!==$v)throw new Exception('Conflicting repeated cell '.$m[0]);$grid[$rn][$col]=trim($v);}
 ksort($grid);$sheets[$sheet->getAttribute('name')]=$grid;
 }return $sheets;}finally{$z->close();}
}
function om_datetime($v,$required=false){$v=trim((string)$v);if($v===''||in_array(strtolower($v),['-','n/a','none'],true)){if($required)throw new Exception('Order creation date is missing.');return null;}if(is_numeric($v)&&(float)$v>30000&&(float)$v<100000)return gmdate('Y-m-d H:i:s',(int)round(((float)$v-25569)*86400));$t=strtotime($v);if($t===false||$t<946684800)throw new Exception('Unrecognized date: '.$v);return date('Y-m-d H:i:s',$t);}
function om_status($platform,$status,$sub='',$delivered='',$ship=''){
 $s=norm($status);$d=norm($sub);if(in_array($s,['failed delivery','delivery failed','delivery_failed','failed_delivery','undeliverable'],true)||in_array($d,['failed delivery','delivery failed','delivery_failed'],true))return 'Failed Delivery';if(in_array($s,['return to sender','return to seller','returning','returned to seller','shipped_back'],true))return 'Return / Refund';if(in_array($s,['cancelled','canceled'],true))return 'Cancelled';if(in_array($s,['unpaid','pending payment'],true))return 'Unpaid';
 if(str_starts_with($s,'order received')||in_array($s,['completed','order received'],true))return 'Completed';if($s==='delivered'||($s==='confirmed'&&$delivered)||($s==='shipped'&&$d==='delivered'))return 'Delivered';
 if(in_array($s,['shipping','shipped','shipped_back','ready_to_ship'],true)){if($s==='ready_to_ship')return 'To Ship';if($platform==='Shopee'&&!$ship)return 'Needs Checking';return 'Shipped';}
 if(in_array($s,['to ship','pending','packed','ready to ship','ready_to_ship'],true))return 'To Ship';if(in_array($s,['returned','refunded','return/refund'],true))return 'Return / Refund';return 'Needs Checking';
}
function om_parse($platform,$path){
 stock_platform($platform);$books=om_book($path);$found=[];$warnings=[];$exactRows=[];$duplicates=0;
 foreach($books as $sheet=>$grid){$header=null;$cols=[];foreach($grid as $rn=>$cells){$h=array_map('norm',$cells);if(in_array($platform==='Lazada'?'ordernumber':'order id',$h,true)&&in_array($platform==='Lazada'?'status':'order status',$h,true)){$header=$rn;$cols=array_flip($h);break;}}
 if($header!==null){$signature=$platform==='Lazada'?'orderitemid':($platform==='TikTok'?'sku id':'sku reference no.');if(!isset($cols[$signature]))throw new Exception('The workbook columns do not match the selected '.$platform.' platform.');}
 if($header===null){if(count($grid)>1)$warnings[]=$sheet.': additional sheet not registered automatically; review the original file (including advance fulfilment).';continue;}
 foreach($grid as $rn=>$cells){if($rn<=$header||!array_filter($cells,fn($v)=>$v!==''))continue;$get=function(...$keys)use($cols,$cells){foreach($keys as $k)if(isset($cols[norm($k)])&&($cells[$cols[norm($k)]]??'')!=='')return $cells[$cols[norm($k)]];return '';};$order=$get($platform==='Lazada'?'ordernumber':'order id');if($platform==='TikTok'&&$rn===$header+1&&str_contains(norm($get('order status')),'current order status'))continue;
 if($order===''||strlen($order)>100||preg_match('/^[0-9.]+[eE][+-]?[0-9]+$/',$order))throw new Exception('Row '.$rn.': invalid Order ID; preserve IDs as text.');
 if($platform!=='Lazada'){$sourceCells=[];foreach($cols as $label=>$col)$sourceCells[$label]=$cells[$col]??'';ksort($sourceCells);$fingerprint=hash('sha256',json_encode($sourceCells));if(isset($exactRows[$fingerprint])){$duplicates++;continue;}$exactRows[$fingerprint]=true;}
 $sku=$get('SKU Reference No.','Seller SKU','sellerSku');$name=$get('Product Name','itemName');$variation=$get('Variation Name','Variation');$external=$platform==='TikTok'?$get('SKU ID'):($platform==='Lazada'?$get('lazadaSku'):$sku);$itemId=$platform==='Lazada'?$get('orderItemId'):'';
 $qty=$platform==='Lazada'?1:whole_number($get('Quantity'),'Row '.$rn.' quantity',1);if($qty>10000000)throw new Exception('Quantity is too large.');if($platform==='Lazada'&&$itemId==='')throw new Exception('Lazada Order Item ID is required.');
 $dateErrors=[];$parseDate=function($value,$label,$required=false)use(&$dateErrors,$order){try{return om_datetime($value,$required);}catch(Throwable $ex){$dateErrors[]='Order '.$order.' / '.$label.': '.$ex->getMessage();return null;}};$created=$parseDate($get('Order Creation Date','Created Time','createTime'),'Order Date',true);$ship=$parseDate($get('Ship Time','Shipped Time'),'Source Shipping Date');$delivered=$parseDate($get('Delivered Time','deliveredDate'),'Delivered Date');$shipSource='';foreach(['Ship Time','Shipped Time'] as $field)if($get($field)!==''){$shipSource=$field;break;}$raw=$get('Order Status','status');$sub=$get('Order Substatus');$after=$get('Return / Refund Status','Cancelation/Return Type');$refund=$get('Order Refund Amount','refundAmount');$returnQty=$get('Returned quantity','Sku Quantity of return');
 if(om_status($platform,$raw,$sub,$delivered,$ship)==='Return / Refund')$after=$after?:'Return / Refund';$af=$after!==''&& !in_array(norm($after),['none','-','n/a','0'],true);if((float)$refund>0)$af=true;if(om_status($platform,$raw,$sub,$delivered,$ship)==='Cancelled')$af=false;
 $key=hash('sha256',json_encode([$external,$sku,$name,$variation]));$line=['row'=>$rn,'sheet'=>$sheet,'order'=>$order,'created'=>$created,'key'=>$key,'sku'=>$sku,'external'=>$external,'item'=>$sku?:$name,'name'=>$name,'variation'=>$variation,'qty'=>$qty,'item_ids'=>$itemId!==''?[$itemId]:[],'status'=>om_status($platform,$raw,$sub,$delivered,$ship),'raw_status'=>$raw.($sub?' / '.$sub:''),'ship_at'=>$ship,'delivered_at'=>$delivered,'ship_source'=>$shipSource,'date_errors'=>$dateErrors,'source_date_rows'=>[['created'=>$created,'ship_at'=>$ship,'delivered_at'=>$delivered,'ship_source'=>$shipSource]],'aftersales'=>$af,'after_raw'=>$after,'return_qty'=>$returnQty,'refund'=>$refund,'tracking'=>$get('Tracking Number*','Tracking ID','trackingCode'),'package'=>$get('Package ID')];if($line['item']==='')throw new Exception('Row '.$rn.': product identity missing.');
 $group=$order.'|'.$key;if($platform==='Lazada'){$unique=$order.'|'.$itemId;$identity=$line;unset($identity['row']);if(isset($found['ids'][$unique])){if($found['ids'][$unique]!==hash('sha256',json_encode($identity)))throw new Exception('Conflicting repeated Lazada item ID '.$itemId);continue;}$found['ids'][$unique]=hash('sha256',json_encode($identity));}
 if(isset($found['lines'][$group])){if($found['lines'][$group]['status']!==$line['status'])$found['lines'][$group]['status']='Needs Checking';$found['lines'][$group]['qty']+=$qty;$found['lines'][$group]['item_ids']=array_merge($found['lines'][$group]['item_ids'],$line['item_ids']);$found['lines'][$group]['aftersales']=$found['lines'][$group]['aftersales']||$af;foreach(['created','ship_at','delivered_at'] as $dateKey){$a=$found['lines'][$group][$dateKey];$b=$line[$dateKey];if($a&&$b&&$a!==$b&&$dateKey==='created')$found['lines'][$group]['date_errors'][]='Order '.$order.': conflicting creation dates across item lines.';if($b&&(!$a||$b>$a))$found['lines'][$group][$dateKey]=$b;}$found['lines'][$group]['date_errors']=array_merge($found['lines'][$group]['date_errors'],$line['date_errors']);$found['lines'][$group]['source_date_rows']=array_merge($found['lines'][$group]['source_date_rows'],$line['source_date_rows']);}else $found['lines'][$group]=$line;
 }
 }if(empty($found['lines']))throw new Exception('No supported '.$platform.' orders found. Upload the original order export with its status columns.');if($duplicates)$warnings[]=$duplicates.' exact repeated source rows were skipped; distinct product lines and quantities were retained.';return ['rows'=>array_values($found['lines']),'warnings'=>$warnings];
}
